from dotenv import load_dotenv
from pydantic import BaseModel, Field
from langchain_core.prompts import ChatPromptTemplate
from langchain_groq import ChatGroq

from app.ai.state import ResearchState


load_dotenv()


class ResearchPlan(BaseModel):
    """Validated research plan generated by the LLM."""

    research_questions: list[str] = Field(
        min_length=3,
        max_length=6,
        description="Three to six distinct questions to investigate.",
    )

    search_queries: list[str] = Field(
        min_length=3,
        max_length=8,
        description="Three to eight specific web search queries.",
    )


planner_prompt = ChatPromptTemplate.from_messages(
    [
        (
            "system",
            """
            You are an expert research planner.

            Create an effective research plan based on the
            topic, intended audience, and requested depth.

            Rules:
            - Generate 3 to 6 distinct research questions.
            - Generate 3 to 8 specific search queries.
            - Cover different important aspects of the topic.
            - Adapt complexity and detail to the audience.
            - Avoid vague, redundant, or overly broad queries.
            - Do not answer the research questions.
            - Return only data matching the required schema.
            """,
        ),
        (
            "human",
            """
            Topic: {topic}
            Audience: {audience}
            Research depth: {depth}

            Create the research plan for this request.
            """,
        ),
    ]
)


planner_llm = ChatGroq(
    model="openai/gpt-oss-20b",
    temperature=0,
)

structured_planner = planner_llm.with_structured_output(
    ResearchPlan,
    method="json_schema",
    strict=True,
)

planner_chain = planner_prompt | structured_planner


def plan_research(state: ResearchState) -> dict:
    """Generate a structured research plan for the graph."""

    plan = planner_chain.invoke(
        {
            "topic": state["topic"],
            "audience": state["audience"],
            "depth": state["depth"],
        }
    )

    return {
        "research_questions": plan.research_questions,
        "search_queries": plan.search_queries,
    }
